using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TwilightSigilEffect", menuName = "Data/Battle/Effects/Moonie/TwilightSigil Effect")]
public class TwilightSigilEffect : Effect
{
	[Header("Action Specifics")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		string localizedEffectOwnerReceiveFormatted = base.localizationManager.GetLocalizedEffectOwnerReceiveFormatted(purify: true, amount);
		return Smart.Format(GetLocalizedDescription(), localizedEffectOwnerReceiveFormatted);
	}

	public void Activate(int diceConvertedAmount)
	{
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		for (int i = 0; i < list.Count; i++)
		{
			int num = list[i].GetComponent<UnitEffects>().IsEffectActiveGetAmount(this);
			if (num > 0)
			{
				CorruptionStats component = list[i].GetComponent<CorruptionStats>();
				for (int j = 0; j < diceConvertedAmount; j++)
				{
					component.Purify(num, null);
				}
			}
		}
	}
}
